import { TopStatLeader } from "../../../Models/TopStatLeader";
import { dbPromise } from "./TopStatLeaderDB";

async function storeTopStatLeader(skater:TopStatLeader):Promise<void>{
    try{
        const db = await dbPromise;
        let transaction:IDBTransaction = db.transaction(["skaterTopStatLeaderStore"], "readwrite");
        let skaterTopStatLeaderStore:IDBObjectStore = transaction.objectStore("skaterTopStatLeaderStore");
    
        let request:IDBRequest<IDBValidKey> = skaterTopStatLeaderStore.add(skater);
        return new Promise<void>((resolve, reject) => {
            request.onsuccess = function(event:Event){
                console.log("Top goal leader has been added to the store", (event.target as IDBRequest<IDBValidKey>).result);
                resolve();
            }
            request.onerror = function(event:Event){
                console.error("Error adding top stat leader to the store", (event.target as IDBRequest).error?.message);
                reject((event.target as IDBRequest).error);
            }
        });
    }catch(error){
        console.error("Failed to connect to the database", error);
        return Promise.reject(error);
    }
}
async function getTopStatLeader(statIndicator:string):Promise<TopStatLeader>{
    try{
        const db = await dbPromise;
        let transaction:  IDBTransaction = db.transaction(["skaterTopStatLeaderStore"]);
        let skaterTopStatLederStore:IDBObjectStore = transaction.objectStore("skaterTopStatLeaderStore")
        let index:IDBIndex = skaterTopStatLederStore.index("statIndicator");

        let request:IDBRequest<TopStatLeader> = index.get(statIndicator);
        return new Promise<TopStatLeader>((resolve, reject) => {
            request.onsuccess = function(event:Event){
                let skaterTopStatLeader:TopStatLeader | undefined = (event.target as IDBRequest<TopStatLeader>).result;
                resolve(skaterTopStatLeader);
            }
            request.onerror = function(event:Event){
                console.error("Error retrieving top stat leader: ", (event.target as IDBRequest).error?.message);
                reject((event.target as IDBRequest).error);
            }
        })
    }catch(error){
        console.error("Failed to connect to the database: ",  error);
        return Promise.reject(error);
    }
}

export {storeTopStatLeader, getTopStatLeader};
